import {newCase,questions,moveCase,safeLink} from './workflow.mjs?v=20261110-quality';
import {episodeDrill} from './episode-drill.mjs';
import {putFile,getFile,deleteFile,clearFiles,validateFile} from './evidence.mjs';
import {dayKey,makePlan,dailyLoad} from './engine.mjs?v=20261101-stepnav';
import {AI_ENDPOINT} from './ai-config.mjs';
import {buildAdviceRequest} from './case-advice.mjs?v=20261110-quality';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Ситуация','Упражнение','Проверка','Итог'];
const phases=['material','discussion','practice','complete'];
let api,urls=[],mount=0,advicePending=false,adviceError='';
function current(){const s=api.getState();s.cases||=[];return s.cases.find(c=>c.id===s.activeCase)||s.cases[0];}
function ensure(){let c=current();const s=api.getState();if(!c){c=newCase(s.profile,crypto.randomUUID(),dayKey());if(s.review?.note)c.note=s.review.note;s.cases=[c];s.activeCase=c.id;api.save();}else if(c.stage==='material'&&!c.note&&!c.files.length&&!c.link){const p=s.profile;c.focus=p.focus;c.team=p.team;c.mode=p.mode;c.build=p.build;c.role=p.team==='Solo'?'Solo':p.role;api.save();}return c;}
function update(next){const s=api.getState();s.cases=s.cases.map(c=>c.id===next.id?next:c);return api.save();}
async function requestAdvice(c,outcomeReview=false){
 if(advicePending||!c||!c.note.trim()||(outcomeReview?!c.outcome.trim():c.answers.length<1))return;
 advicePending=true;adviceError='';api.render();
 try{
  const s=api.getState(),payload=buildAdviceRequest(c,s.profile,s.checkins[dayKey()],outcomeReview,s.stats,s.aiMessages,s);
  const response=await fetch(AI_ENDPOINT+'/analysis',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
  const data=await response.json();
  if(!response.ok)throw Error(data.error==='player_daily_limit'?'Сегодня ответы тренера закончились. Продолжи завтра.':data.error==='daily_limit'?'Общий дневной запас AI закончился. Попробуй завтра.':'Тренер сейчас не ответил. Попробуй позже.');
  if(typeof data.answer!=='string'||!data.answer.trim())throw Error('Тренер вернул пустой ответ. Попробуй позже.');
  const live=s.cases.find(x=>x.id===c.id);
  if(live){live[outcomeReview?'aiOutcomeAdvice':'aiAdvice']=data.answer.trim().slice(0,4500);api.save();}
 }catch(error){adviceError=error.message||'Не удалось получить разбор.';}
 finally{advicePending=false;api.render();}
}
const field=(key,label,value,placeholder='',required=true)=>`<div class="field"><label for="case-${key}">${label}</label><textarea id="case-${key}" data-case-field="${key}" maxlength="${['action','measure','next'].includes(key)?1000:3000}" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea></div>`;
function chat(c){const prompt=/хг|хайграунд|high.?ground/i.test(c.note)?'Что именно произошло на ХГ: ты сорвался при спуске или соперник выбил опору? Что ты видел, какое решение принял и где потерял контроль?':questions(c)[0];return `<section class="card ws-chat" id="ws-chat"><div class="ws-chat-head"><span class="badge lime">ЦЕПОЧКА РЕШЕНИЯ</span><h2>Почему так вышло?</h2><p>Что ты знал в тот момент → какое решение принял → что произошло? Возможную причину пометь как гипотезу.</p></div>${c.stage==='discussion'&&!c.answers.length?`<form id="ws-answer" class="ws-compose"><label for="ws-message">${esc(prompt)}</label><textarea id="ws-message" name="answer" maxlength="2000" required placeholder="Факт → решение → результат. Что было неизвестно?">${esc(c.answerDraft||'')}</textarea><button class="btn" type="submit">Сохранить цепочку →</button></form>`:`<div class="ws-compose"><p>${c.answers.length?esc(c.answers[0]):'Опиши ситуацию слева, чтобы начать.'}</p>${c.stage==='discussion'&&c.answers.length?'<button class="btn secondary small" type="button" data-ws-edit-answer>Изменить цепочку</button>':''}</div>`}<a href="#coach" class="ws-coach-link">Обсудить глубже с AI-тренером →</a></section>`;}
function files(c){return `<section class="ws-files"><h3>Клип, скриншот или результат</h3><p>До 3 файлов, суммарно 100 МБ. Для командной игры полезен короткий клип с войсами. Можно начать только с описания.</p><label class="ws-upload">＋ Прикрепить файл<input id="ws-file" type="file" accept=".mp4,.webm,.png,.jpg,.jpeg,.webp,.replay"></label><p class="ws-local">Файлы сохраняются в этом браузере и не передаются AI-тренеру автоматически. Видео MP4/WebM можно просмотреть здесь. Формат .replay браузер открыть не умеет: для разбора экспортируй нужный момент в видео или опиши его словами.</p><div id="ws-files">${c.files.map(f=>`<div class="ws-file" data-file-id="${esc(f.id)}"><div class="ws-file-top"><strong>${esc(f.name)}</strong><span>${(f.size/1048576).toFixed(1)} МБ</span><button type="button" class="btn ghost" data-remove-file="${esc(f.id)}" aria-label="Удалить ${esc(f.name)}">Удалить</button></div><div data-preview="${esc(f.id)}"><p>Загрузка локального файла…</p></div></div>`).join('')}</div></section>`;}
export function renderWorkspace(){const c=ensure(),step=phases.indexOf(c.stage),next=['Опиши один момент','Запиши цепочку и выбери упражнение','Выполни упражнение и запиши результат','Итог сохранён. Выбери следующий эпизод'][step];
 const s=api.getState(),check=s.checkins[dayKey()],light=check&&dailyLoad(check)==='light',minutes=makePlan(s.profile,check||{}).reduce((n,t)=>n+t.minutes,0);
 const drills=makePlan(s.profile,check||{}),suggestion=episodeDrill(c.note,c.answers[0]);
 const todayTask=check?`<div class="ws-today"><span class="eyebrow">ОТДЕЛЬНАЯ ТРЕНИРОВКА НА СЕГОДНЯ · ДО ${esc(check.minutes||s.profile.minutes)} МИН · ${esc(dayKey())}</span><h2>${esc(drills[1].title)}</h2><p><strong>Что сделать.</strong> ${esc(drills[1].steps[0])}</p><p><strong>Что записать.</strong> ${esc(drills[1].metric)}</p><p>Это самостоятельная тренировка по твоему профилю и состоянию. Ниже — отдельный разбор выбранного тобой эпизода; упражнение для него будет связано с описанной ситуацией.</p><p class="ws-today-note">Время — твой доступный максимум, не обязательная длительность. Закончил проверку раньше — остановись. ${light?'Сегодня можно работать с записью вместо игры.':'Если осталось время, повтори проверку в похожей ситуации.'}</p><a href="#dashboard">Изменить самочувствие и время →</a></div>`:`<div class="ws-today ws-today-empty"><strong>Сначала отметь состояние на сегодня</strong><p>Сон, энергия и доступное время помогут выбрать посильное упражнение.</p><a href="#dashboard">Отметить на главной →</a></div>`;
 const adviceBox=c.answers.length>=1?`<section class="ws-ai-advice"><span class="eyebrow">РАЗБОР ОТ AI-ТРЕНЕРА</span><h2>Что видно из твоего эпизода</h2>${c.aiAdvice?`<p class="ws-advice-text">${esc(c.aiAdvice)}</p>`:`<p>Твои ответы уже есть. Тренер сопоставит их с ролью, режимом и сегодняшней нагрузкой и предложит одно проверяемое изменение. Он читает только текст — файл автоматически не просматривает.</p><button class="btn" type="button" data-ws-ai-review ${advicePending?'disabled':''}>${advicePending?'Тренер разбирает…':'Получить разбор и упражнение →'}</button>`}${adviceError?`<p class="error" role="alert">${esc(adviceError)}</p>`:''}</section>`:'';
 const outcomeBox=`<section class="ws-ai-advice ws-ai-outcome"><span class="eyebrow">ВЕРДИКТ ПО РЕЗУЛЬТАТУ</span><h2>Что дала эта проверка?</h2>${c.aiOutcomeAdvice?`<p class="ws-advice-text">${esc(c.aiOutcomeAdvice)}</p>`:`<p>Тренер сопоставит твою цель и записанный результат. Если данных мало, скажет прямо, что оценить нельзя, и уточнит одну деталь.</p><button class="btn" type="button" data-ws-ai-outcome ${advicePending?'disabled':''}>${advicePending?'Тренер разбирает…':'Получить вердикт и следующий шаг →'}</button>`}${adviceError?`<p class="error" role="alert">${esc(adviceError)}</p>`:''}</section>`;
 const material=`${c.focus.startsWith('Общий импрув')?'<div class="ws-task"><h2>Начнём без готового диагноза</h2><p>Выбери один момент, который хочешь улучшить. Достаточно короткого описания — дальше перейдём к упражнению.</p><a href="#coach">Обсудить с AI →</a></div>':''}<form id="ws-material">${field('note','Что произошло и что хочешь разобрать?',c.note,c.focus.startsWith('Общий импрув')?'Опиши один момент: что заметил, что сделал и чем закончилась ситуация. Если причина непонятна — так и напиши.':'Например: проиграли контест. На 00:42 пошёл в файт, пока тиммейт ещё лутался. Думаю, начали раздельно.')}<div class="field"><label for="case-link">Ссылка на клип или результаты — необязательно</label><input id="case-link" data-case-field="link" type="url" value="${esc(c.link)}" placeholder="https://…"><p>Ссылка сохраняется для открытия вручную. Импорт статистики не подключён.</p></div>${files(c)}<button class="btn" type="submit">Выбрать упражнение →</button></form>`;
 const source=`<details class="ws-source"><summary>Материал и твоя версия</summary><p class="ws-preserve">${esc(c.note)}</p>${c.link?`<a href="${esc(safeLink(c.link))}" target="_blank" rel="noopener noreferrer">Открыть прикреплённую ссылку ↗</a>`:''}${files(c)}</details>`;
 const practiceForm=`<section><h2>Что проверишь в игре</h2><p>Сформулируй решение, которое зависит от тебя. Укажи условия, при которых оно применимо.</p><div class="ws-suggestion"><strong>Подсказка по твоей цепочке:</strong> ${esc(suggestion.title)}<p>${c.answers.length?'Ниже уже предложено конкретное действие. Проверь, совпадает ли оно с твоим эпизодом, и исправь при необходимости.':'Сначала опиши причину справа — тогда упражнение уточнится автоматически.'}</p></div><form id="ws-practice">${field('action','Что конкретно сделаешь в следующем похожем моменте?',c.action,'Например: перед заходом на соперника дождаться подтверждения тиммейта, что он готов к размену.')}<p class="ws-local">Проверка: ${esc(c.measure||suggestion.measure)}</p><button class="btn" type="submit" ${c.answers.length<1?'disabled':''}>Сохранить и перейти к практике →</button>${c.answers.length<1?'<p>Сначала запиши цепочку событий справа.</p>':''}</form></section>${adviceBox}`;
 const resultForm=`${adviceBox}<div class="ws-task"><span class="badge lime">ТВОЯ ЗАДАЧА В ИГРЕ</span><h2>${esc(c.action)}</h2><p><strong>Проверка:</strong> ${esc(c.measure)}</p></div><form id="ws-finish"><h2>Вернулся с практики?</h2>${field('outcome','Что получилось на практике?',c.outcome,'Сколько подходящих ситуаций было? В скольких выполнил решение? Что помешало? Если не было подходящих ситуаций — запиши это.')}${field('next','Что сделаешь дальше?',c.next,'Повторю проверку с тем же условием / изменю условие / разберу следующий момент…')}<button class="btn" type="submit">Сохранить итог в журнал →</button></form>`;
 const complete=`${outcomeBox}${adviceBox}<span class="badge lime">ИТОГ СОХРАНЁН</span><h2>Один эпизод доведён до результата</h2><dl class="ws-summary"><dt>Что проверял</dt><dd>${esc(c.action)}</dd><dt>Как проверял</dt><dd>${esc(c.measure)}</dd><dt>Твой результат</dt><dd>${esc(c.outcome)}</dd><dt>Следующий шаг</dt><dd>${esc(c.next)}</dd></dl><p>Это твои наблюдения, а не автоматическая оценка скилла.</p><div class="actions"><button class="btn" data-ws-new>Начать следующий разбор →</button><a class="btn secondary" href="#journal">Открыть журнал</a></div>`;
 return `<div class="workspace" data-phase="${c.stage}" data-answered="${c.answers.length>=1}"><div class="ws-heading"><div><span class="eyebrow">ТВОЯ ПРАКТИКА · ${esc(c.mode)} · ${esc(c.team)} · ${esc(c.role)}</span><h1>Проверь решение в практике.</h1><p>Один момент → цепочка причин → упражнение → измеримый результат.</p></div><a href="#dashboard" class="btn secondary">Самочувствие</a></div>${todayTask}<ol class="ws-steps ws-steps-three" aria-label="Этапы разбора">${['Ситуация','Практика','Итог'].map((n,i)=>{const active=step===0?0:step===1?1:2;return `<li><button type="button" class="ws-step-button ${i===active?'current':i<active?'passed':''}" data-ws-step="${i}" ${i===active?'aria-current="step"':''} aria-label="Открыть шаг: ${n}"><span>${i<active?'✓':i+1}</span>${n}</button></li>`}).join('')}</ol><div class="ws-next"><strong>Сейчас: ${next}</strong><span id="ws-save-status" role="status">Изменения сохраняются в браузере</span></div><div class="ws-layout"><div class="card ws-work">${c.stage==='material'?material:c.stage==='discussion'?practiceForm:c.stage==='practice'?resultForm:complete}${c.stage!=='material'?source:''}</div>${chat(c)}</div>${history()}${api.getState().messages.length?`<details class="card ws-source"><summary>Диалог из предыдущей версии</summary>${api.getState().messages.map(m=>`<p class="ws-preserve"><strong>${m.role==='user'?'Ты':'Помощник'}:</strong> ${esc(m.text)}</p>`).join('')}</details>`:''}<p class="ws-local">Профиль, разборы и файлы доступны только на этом устройстве и в этом браузере. Экспорт в профиле сохраняет текст, но не медиафайлы.</p></div>`;
}
function openStep(index,c){
 let selector='';
 if(index===0){if(c.stage!=='material'){update(moveCase(c,'back',{to:'material'}));api.render();}selector='#case-note';}
 else if(index===1){if(c.stage==='material'){selector='#case-note';api.toast('Сначала опиши ситуацию и нажми «Выбрать упражнение».');}else{if(c.stage!=='discussion'){update(moveCase(c,'back',{to:'discussion'}));api.render();}selector='#ws-practice';}}
 else if(index===2){if(c.stage==='practice')selector='#ws-finish';else if(c.stage==='complete')selector='.ws-summary';else{selector=c.stage==='material'?'#case-note':'#ws-practice';api.toast('Итог откроется после выбора упражнения.');}}
 const target=document.querySelector(selector);if(!target)return;target.scrollIntoView({behavior:'smooth',block:'center'});if(['TEXTAREA','INPUT'].includes(target.tagName))target.focus({preventScroll:true});
}
function history(){const s=api.getState();return s.cases.length?`<section class="card ws-history"><h2>Мои разборы</h2>${s.cases.map(c=>`<div class="ws-history-row"><button class="ws-history-item" data-ws-open="${esc(c.id)}"><span>${esc(c.date)} · ${esc(c.focus)}</span><strong>${esc(c.note.slice(0,90)||'Новый эпизод')}</strong><span>${names[phases.indexOf(c.stage)]} →</span></button><button class="ws-history-delete" type="button" data-ws-delete="${esc(c.id)}" aria-label="Удалить разбор ${esc(c.note.slice(0,50)||'Новый эпизод')}">Удалить</button></div>`).join('')}</section>`:'';}
export function releaseWorkspace(){mount++;urls.forEach(u=>URL.revokeObjectURL(u));urls=[];}
export async function mountWorkspace(){const generation=mount,c=current();if(!c||!document.querySelector('.workspace'))return;const log=document.querySelector('.ws-messages');if(log)log.scrollTop=log.scrollHeight;
 for(const f of c.files){const target=document.querySelector(`[data-preview="${f.id}"]`);if(!target)continue;
  try{const row=await getFile(f.id);if(generation!==mount)return;target.replaceChildren();if(!row){target.textContent='Файл недоступен в этом браузере. Прикрепи его заново; текст разбора сохранён.';continue;}const url=URL.createObjectURL(row.file);urls.push(url);let media;
   if(/^image\/(png|jpeg|webp)$/.test(row.file.type)){media=document.createElement('img');media.alt='Скриншот для разбора';}
   else if(/^video\/(mp4|webm)$/.test(row.file.type)){media=document.createElement('video');media.controls=true;media.preload='metadata';}
   if(media){media.src=url;media.className='ws-media';media.addEventListener('error',()=>{const p=document.createElement('p');p.textContent='Браузер не поддерживает воспроизведение этого файла. Его можно скачать.';target.append(p);},{once:true});target.append(media);}
   const a=document.createElement('a');a.href=url;a.download=f.name;a.textContent='Скачать файл';target.append(a);
  }catch{target.textContent='Не удалось открыть локальное хранилище. Текст разбора доступен.';}
 }
}
export function installWorkspace(options){api=options;
 document.addEventListener('click',async e=>{const button=e.target.closest('[data-ws-delete]');if(!button)return;const s=api.getState(),id=button.dataset.wsDelete,found=s.cases?.find(x=>x.id===id);if(!found)return;if(!confirm(`Удалить разбор «${found.note.slice(0,70)||'Новый эпизод'}» и его файлы?`))return;button.disabled=true;const oldCases=s.cases,oldSessions=s.sessions,oldActive=s.activeCase;s.cases=oldCases.filter(x=>x.id!==id);s.sessions=oldSessions.filter(x=>x.caseId!==id);if(oldActive===id)s.activeCase=s.cases[0]?.id;if(!api.save()){s.cases=oldCases;s.sessions=oldSessions;s.activeCase=oldActive;button.disabled=false;return;}for(const file of found.files){try{await deleteFile(file.id);}catch{api.toast('Разбор удалён, но один локальный файл очистить не удалось.');}}api.render();api.toast('Разбор удалён.');});
 document.addEventListener('input',e=>{const key=e.target.dataset.caseField,c=current();if(!c)return;if(key&&['note','link','action','measure','outcome','next'].includes(key)){if(key==='note'&&c.note!==e.target.value){const oldDrill=episodeDrill(c.note,c.answers[0]);if(c.action===oldDrill.action){c.action='';c.measure='';}if(c.answers.length){c.answerDraft=c.answers[0];c.answers=[];}}c[key]=e.target.value;if(key==='note'){c.aiAdvice='';c.aiOutcomeAdvice='';}if(['action','measure','outcome'].includes(key))c.aiOutcomeAdvice='';const ok=api.save();const status=document.querySelector('#ws-save-status');if(status)status.textContent=ok?'Черновик сохранён':'Не удалось сохранить';}if(e.target.id==='ws-message'){c.answerDraft=e.target.value;api.save();}});
 document.addEventListener('submit',e=>{if(!e.target.id.startsWith('ws-'))return;e.preventDefault();const c=current();try{let next;if(e.target.id==='ws-material'){if(c.link&&!safeLink(c.link))throw Error('Укажи HTTPS-ссылку без логина и пароля.');next=moveCase(c,'discuss');}if(e.target.id==='ws-answer'){next=moveCase(c,'answer',{text:new FormData(e.target).get('answer')});delete next.answerDraft;const drill=episodeDrill(next.note,next.answers[0]);if(!next.action||next.action===episodeDrill(next.note).action){next.action=drill.action;next.measure=drill.measure;}}if(e.target.id==='ws-practice'){c.measure=episodeDrill(c.note,c.answers[0]).measure;next=moveCase(c,'practice');}if(e.target.id==='ws-finish'){next=moveCase(c,'finish');const s=api.getState();s.sessions=s.sessions.filter(x=>x.caseId!==c.id);s.sessions.unshift({caseId:c.id,date:dayKey(),type:'Разбор и практика',matches:0,early:0,note:`Проверка: ${c.action}\nКритерий: ${c.measure}\nРезультат: ${c.outcome}\nДальше: ${c.next}`.slice(0,3000)});s.sessions=s.sessions.slice(0,365);}if(next){const ok=update(next);api.render();if(next.stage==='discussion'&&next.answers.length<1)document.querySelector('#ws-message')?.focus();else document.querySelector('.ws-next')?.scrollIntoView({block:'start'});if(ok)api.toast(next.stage==='complete'?'Итог сохранён в журнал. Следующий шаг — на экране.':'Шаг сохранён.');}}catch(error){api.toast(error.message);}});
 document.addEventListener('change',async e=>{if(e.target.id!=='ws-file')return;const file=e.target.files[0],c=current();if(!file||!c)return;const id=crypto.randomUUID(),button=e.target;button.disabled=true;try{validateFile(file,c.files);await putFile(id,file);const live=api.getState().cases?.find(x=>x.id===c.id);if(!live){await deleteFile(id);return;}try{validateFile(file,live.files);}catch(error){await deleteFile(id);throw error;}live.files.push({id,name:file.name,size:file.size,type:file.type});if(!api.save()){live.files.pop();await deleteFile(id);return;}api.render();api.toast('Файл прикреплён и сохранён в этом браузере.');}catch(error){api.toast(error.message?.startsWith('Максимум')||error.message?.startsWith('Поддерживаются')||error.message?.startsWith('В одном')?error.message:'Не удалось сохранить файл: проверь свободное место или разрешения браузера.');}finally{button.disabled=false;button.value='';}});
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const c=current(),s=api.getState();if(b.hasAttribute('data-ws-edit-answer')){const oldDrill=episodeDrill(c.note,c.answers[0]);if(c.action===oldDrill.action){c.action='';c.measure='';}c.answerDraft=c.answers[0]||'';c.answers=[];c.aiAdvice='';c.aiOutcomeAdvice='';api.save();api.render();document.querySelector('#ws-message')?.focus();return;}if(b.hasAttribute('data-ws-step')){openStep(Number(b.dataset.wsStep),c);return;}if(b.hasAttribute('data-ws-ai-review')){await requestAdvice(c);return;}if(b.hasAttribute('data-ws-ai-outcome')){await requestAdvice(c,true);return;}if(b.dataset.removeFile){b.disabled=true;try{await deleteFile(b.dataset.removeFile);const live=s.cases?.find(x=>x.id===c.id);if(live)live.files=live.files.filter(f=>f.id!==b.dataset.removeFile);api.save();api.render();}catch{api.toast('Не удалось удалить файл.');b.disabled=false;}}if(b.dataset.wsOpen){s.activeCase=b.dataset.wsOpen;api.save();if(!["#plan","#coach","#review"].includes(location.hash))location.hash="plan";else api.render();window.scrollTo(0,0);}if(b.hasAttribute('data-ws-new')){if(s.cases.length>=30){api.toast('Сохранено 30 разборов. Экспортируй данные перед очисткой в профиле.');return;}const n=newCase(s.profile,crypto.randomUUID(),dayKey());s.cases.unshift(n);s.activeCase=n.id;api.save();api.render();window.scrollTo(0,0);}});
}
export async function resetEvidence(){try{await clearFiles();}catch{api.toast('Текст удалён, но очистить файлы не удалось. Удали данные сайта в настройках браузера.');}}
